<?php
session_start();
header("X-Frame-Options: DENY");
if(!isset($_SESSION['user_id']) || !isset($_SESSION['login_time'])){ header('Location: login.php'); exit; }
if(time() - $_SESSION['login_time'] > 3600){ session_destroy(); header('Location: login.php'); exit; }
$_SESSION['login_time']=time();
$data=json_decode(file_get_contents(__DIR__.'/fake_db.json'),true);
$uid=$_SESSION['user_id']; $my=[]; foreach($data['complaints'] as $c){ if($c['user_id']==$uid) $my[]=$c; }
$myRev=array_reverse($my);
$total=count($myRev); $pend=0; $closed=0; foreach($myRev as $c){ if(strtolower($c['status'])=='pending')$pend++; if(strtolower($c['status'])=='closed'||strtolower($c['status'])=='resolved')$closed++; }
?>
