 14px;border-radius:10px;font-size:11px;font-weight:700;text-decoration:none}.btn-primary{background:linear-gradient(135deg,#5a4cf1,#7c3aed);color:#fff;box-shadow:0 4px 12px rgba(90,76,241,.3)}.btn-ghost{background:#f8f7ff;color:#111827;border:1.5px solid #eee8ff}</style></head><body><div class="sidebar"><div class="logo"><div class="logo-i">💬</div><div><div style="font-weight:800;color:#fff;font-size:14px">ResolveDesk</div><div style="font-size:10px">Student Portal 🔒</div></div></div><div class="profile"><div style="width:36px;height:36px;background:linear-gradient(135deg,#f59e0b,#ec4899);border-radius:10px;display:flex;align-items:center;justify-content:center;color:#fff;font-weight:800;font-size:13px"><?php echo strtoupper(substr($_SESSION['user_name'],0,1)); ?></div><div><div style="font-weight:700;color:#fff;font-size:12px"><?php echo htmlspecialchars($_SESSION['user_name']); ?></div><div style="font-size:10px">Student</div></div></div><a class="m-item" href="dashboard.php">◎ Dashboard</a><a class="m-item active" href="my_complaints.php">☰ My Complaints <span style="margin-left:auto;background:#fff;color:#0a0a1a;font-size:10px;font-weight:800;width:20px;height:20px;border-radius:50%;display:flex;align-items:center;justify-content:center"><?php echo $total; ?></span></a><a class="m-item" href="submit_complaint.php">✦ New Complaint</a><a class="m-item" href="logout.php">↪ Logout</a></div><div class="main"><div class="top"><div><div style="font-size:11px;color:#6b7280">Student / My Complaints • 🔒 Secure</div><div style="font-weight:800;font-size:22px;margin-top:2px">My Complaints 📋</div><div style="font-size:12px;color:#6b7280;margin-top:2px">Track all your complaints with full details - <?php echo $total; ?> total</div></div><a href="submit_complaint.php" class="btn btn-primary">+ New Complaint</a></div><div class="stats"><div class="sc"><div style="font-size:11px;color:#6b7280;font-weight:700">TOTAL</div><div style="font-size:22px;font-weight:800;margin-top:4px"><?php echo $total; ?></div></div><div class="sc"><div style="font-size:11px;color:#6b7280;font-weight:700">PENDING</div><div style="font-size:22px;font-weight:800;color:#d97706;margin-top:4px"><?php echo $pend; ?></div></div><div class="sc"><div style="font-size:11px;color:#6b7280;font-weight:700">RESOLVED</div><div style="font-size:22px;font-weight:800;color:#16a34a;margin-top:4px"><?php echo $closed; ?></div></div></div><div class="card"><div style="padding:16px 18px;font-weight:800;font-size:14px;border-bottom:1px solid #f8f5ff;display:flex;justify-content:space-between"><span>All Complaints - Detailed View</span><span style="font-size:11px;color:#6b7280;font-weight:500">🔒 Secure & Encrypted</span></div><?php foreach($myRev as $c){ ?><div class="row"><div style="display:flex;gap:14px;align-items:flex-start"><div style="width:48px;height:48px;background:linear-gradient(135deg,#f8f7ff,#eef2ff);border:1px solid #e0d7ff;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:20px"><?php echo strtolower($c['category'])=='hostel'?'🏠':(strtolower($c['category'])=='academics'?'🎓':'📝'); ?></div><div><div style="display:flex;gap:8px;align-items:center"><div style="font-weight:800;font-size:13px">CMP-<?php echo str_pad($c['id'],6,'0',STR_PAD_LEFT); ?></div><span class="badge <?php echo strtolower($c['status'])=='pending'?'b-pend':(strtolower($c['status'])=='in progress'?'b-prog':'b-close'); ?>"><?php echo htmlspecialchars($c['status']); ?></span><span style="padding:4px 8px;background:#f8f7ff;border-radius:6px;font-size:10px;font-weight:600"><?php echo htmlspecialchars($c['category']); ?></span></div><div style="font-weight:700;font-size:13px;margin-top:4px"><?php echo htmlspecialchars($c['subject']); ?></div><div style="font-size:11px;color:#6b7280;margin-top:2px">📍 <?php echo htmlspecialchars($c['location']); ?> • 📅 <?php echo htmlspecialchars($c['created_at']); ?></div><div style="font-size:12px;color:#374151;margin-top:6px;background:#f9fafb;border:1px solid #f3f4f6;padding:8px 10px;border-radius:8px;max-width:420px"><?php echo htmlspecialchars($c['description']); ?></div><?php if(!empty($c['admin_response'])){ ?><div style="font-size:11px;color:#166534;margin-top:6px;background:#f0fdf4;border:1px solid #bbf7d0;padding:6px 10px;border-radius:8px"><b>💬 Admin:</b> <?php echo htmlspecialchars($c['admin_response']); ?></div><?php } ?></div></div><div style="display:flex;flex-direction:column;gap:8px"><a href="complaint_details.php?id=<?php echo $c['id']; ?>" class="btn btn-primary">View Details →</a><div style="font-size:10px;color:#9ca3af;text-align:center">ID: <?php echo $c['id']; ?></div></div></div><?php } if(empty($myRev)){ echo '<div style="padding:40px;text-align:center;color:#6b7280"><div style="font-size:40px">📭</div><div style="font-weight:700;margin-top:10px">No complaints yet</div><div style="font-size:12px;margin-top:4px">Submit your first complaint</div><a href="submit_complaint.php" class="btn btn-primary" style="display:inline-block;margin-top:12px">+ New Complaint</a></div>'; } ?></div></div></body></html>
